CREATE TABLE IF NOT EXISTS leave_attachments (id INT PRIMARY KEY AUTO_INCREMENT, leave_application_id INT NOT NULL, document_type ENUM('study_timetable', 'medical_certificate') NOT NULL, file_name VARCHAR(255) NOT NULL, file_path VARCHAR(500) NOT NULL, file_size INT NOT NULL, file_extension VARCHAR(10) NOT NULL, mime_type VARCHAR(100) NOT NULL, uploaded_by INT NOT NULL, uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (leave_application_id) REFERENCES leave_applications(id) ON DELETE CASCADE, FOREIGN KEY (uploaded_by) REFERENCES users(id), INDEX idx_leave_application (leave_application_id), INDEX idx_document_type (document_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; 
